def is_connected(adj_matrix, vertices):
    n = len(vertices)
    visited = [False] * n
    def dfs(i):
        stack = [i]
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                for j in range(n):
                    if adj_matrix[node][j] and not visited[j]:
                        stack.append(j)
    if n == 0:
        return True
    dfs(0)
    return all(visited)

def list_to_matrix(adj_list, vertices):
    n = len(vertices)
    matrix = [[0] * n for _ in range(n)]
    index = {v: i for i, v in enumerate(vertices)}
    for u in adj_list:
        for v in adj_list[u]:
            matrix[index[u]][index[v]] = 1
    return matrix
